const $=id=>document.getElementById(id),key='hopeEventParticipantV1';let token=sessionStorage.getItem(key),state=null,busy=false;
function message(text,error=false){$('message').textContent=text;$('message').dataset.error=String(error);}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok)throw Object.assign(Error(b.error||'目前無法連線，請再試一次。'),{status:r.status});return b;}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){message(e.message,true);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function render(){if(!state)return;$('join-form').hidden=true;$('journey').hidden=false;$('event-name').textContent=state.title;$('welcome').textContent=`${state.name}，歡迎來到希望島。`;$('steps').replaceChildren();for(let i=0;i<state.total;i++){const li=document.createElement('li');li.textContent=`第 ${i+1} 題${i<state.progress?'・已完成':''}`;li.dataset.done=String(i<state.progress);$('steps').append(li);}$('choices').replaceChildren();$('feedback').replaceChildren();$('next').hidden=true;$('complete-link').hidden=!state.completedAt;$('closed-note').textContent=state.active?'':'活動目前已結束，已完成的進度仍會保留。';
 if(state.completedAt){$('question-title').textContent='三題全數答對，恭喜通關！';$('feedback').textContent='你已完成今天的希望旅程。回到島上，為自己點亮一顆願望星星。';return;}
 $('question-title').textContent=state.question.prompt;if(!state.active)return;
 state.question.choices.forEach((choice,i)=>{const button=document.createElement('button');button.textContent=choice;button.onclick=()=>run(async()=>{const result=await api('participant/answer',{index:state.progress,choice:i});if(!result.correct){$('feedback').textContent=result.explanation;return;}state=result;$('choices').replaceChildren();$('feedback').textContent=result.explanation;for(const source of result.sources||[]){const a=document.createElement('a');a.textContent=source.label;a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';$('feedback').append(document.createElement('br'),a);}$('next').textContent=result.completedAt?'查看通關紀錄':'下一題';$('next').hidden=false;$('next').focus();message('答對了，進度已儲存。');});$('choices').append(button);});}
$('code').value=new URLSearchParams(location.search).get('code')||'';
$('join-form').onsubmit=e=>{e.preventDefault();run(async()=>{state=await api('events/join',{code:$('code').value,name:$('name').value,role:$('role').value,color:$('color').value});token=state.token;sessionStorage.setItem(key,token);render();message('已加入活動，角色將出現在島上。');$('question-title').focus();});};
$('next').onclick=()=>{render();$('question-title').focus();};$('leave').onclick=()=>{if(!confirm('切換後需要重新加入。確定交給下一位參加者或切換活動嗎？'))return;sessionStorage.removeItem(key);token=null;state=null;$('join-form').reset();$('join-form').hidden=false;$('journey').hidden=true;message('已結束此裝置的參加工作階段。');};
if(token)run(async()=>{try{state=await api('participant');render();}catch(e){if(e.status===401){sessionStorage.removeItem(key);token=null;}throw e;}});
